# Now compare with the established measurement
meas = snapshot["dependency_concentration"]["measurement"]
print("Established measurement worker_count:", meas["worker_count"])
print()

for dtype in ["engine", "trigger", "effect", "digest"]:
    print(f"=== {dtype.upper()} comparison ===")
    established = {e["identity"]: (e["worker_count"], e["fleet_share"]) for e in meas["by_type"][dtype]}
    if dtype == "engine":
        recomputed = {k: (v, v/total) for k, v in engine_counts.items()}
    elif dtype == "trigger":
        recomputed = {k: (v, v/total) for k, v in trigger_counts.items()}
    elif dtype == "effect":
        recomputed = {k: (v, v/total) for k, v in effect_counts.items()}
    elif dtype == "digest":
        recomputed = {k: (v, v/total) for k, v in digest_counts.items()}

    all_keys = set(established.keys()) | set(recomputed.keys())
    match = True
    for k in all_keys:
        e_val = established.get(k, (0, 0))
        r_val = recomputed.get(k, (0, 0))
        if e_val[0] != r_val[0] or abs(e_val[1] - r_val[1]) > 0.0001:
            print(f"  MISMATCH {k}: established={e_val}, recomputed={r_val}")
            match = False
    if match:
        print(f"  ALL MATCH for {len(all_keys)} identities")
    print()

# Check individual worker issues
print("=== Individual worker issues ===")
for w in workers:
    s = w["summary"]
    issues = []
    if s["last_status"] != "ok":
        issues.append(f"last_status={s['last_status']}")
    if s["exceptions"] > 0:
        issues.append(f"exceptions={s['exceptions']}")
    if s["effects_failed"] > 0:
        issues.append(f"effects_failed={s['effects_failed']}")
    if w.get("investigation"):
        issues.append(f"investigation={w['investigation']['state']}")
    if issues:
        print(f"  {w['name']}: {', '.join(issues)}")

# Check the pending exception
print("\n=== Pending exceptions ===")
for pe in snapshot.get("pending_exceptions", []):
    print(f"  {pe['worker']}: {pe['state']} - {pe['failure']}")

# Task type distribution
task_counts = Counter(w["task"] for w in workers)
print("\n=== Task type distribution ===")
for t, c in task_counts.most_common():
    print(f"  {t}: {c}")

# Customer distribution
cust_counts = Counter(w["customer"] for w in workers)
print("\n=== Customer distribution ===")
for c, cnt in cust_counts.most_common():
    print(f"  {c}: {cnt}")
